mapper.select:
SELECT a.*, a.account_id AS open_id, u.nick_name AS user_name, u.phone FROM sys_account a LEFT JOIN sys_user u ON a.user_id = u.user_id
a.del_flag != ${pageDTO.delFlag}
AND a.user_id = ${pageDTO.userId}
AND a.open_id = ${pageDTO.openId}
AND u.nick_name LIKE CONCAT('%',${pageDTO.userName},'%')
AND a.nick_name LIKE CONCAT('%',${pageDTO.nickName},'%')
